import numpy as np, torch, model
torch.manual_seed(2)
net=model.load()
w=torch.tensor(np.load('det_8_12.npy')); b=float(np.load('detb_8_12.npy')[0]); THR=1.0
st={'k':0,'on':False,'M':torch.zeros(2,2),'d':torch.zeros(2),'lo':8,'hi':12,'x':None}
def pre(m,args,kw):
    st['x']=args[0]
net.register_forward_pre_hook(pre,with_kwargs=True)
def hook(m,inp,out):
    k=st['k']; st['k']+=1
    if not st['on']: return out
    f=((inp[0]@w+b>THR)&(st['lo']<=k)&(k<st['hi'])).float()[:,None]
    return out+f*(st['x']@st['M'].T+st['d'])
net.out.register_forward_hook(hook)
B=6144; xd=torch.randn(B,2); cd=torch.rand(B); c=cd.numpy()
def run(on,M=None,d=None,lo=8,hi=12):
    st.update(k=0,on=on,lo=lo,hi=hi)
    if M is not None: st['M']=torch.tensor(M,dtype=torch.float32)
    if d is not None: st['d']=torch.tensor(d,dtype=torch.float32)
    with torch.no_grad(): return np.asarray(model.decode(net,xd,cd))
def track(a):
    th=np.degrees(np.arctan2(a[:,1],a[:,0]))%360; dth=((th-(182.16+64.94*c)+180)%360)-180
    return (np.abs(dth)<20)&(np.linalg.norm(a,axis=1)>1.5)
a0=run(False); l0=track(a0); ref=torch.tensor(a0)
nn0=torch.cdist(ref,ref).topk(2,largest=False).values[:,1].numpy(); q=np.quantile(nn0,0.99)
def off(a): return (torch.cdist(torch.tensor(a),ref).min(1).values.numpy()>q).mean()
print('base track',l0.mean(), 'off',off(a0))
R=np.array([[0,-1],[1,0]])
cfgs=[]
for s in [2,4,8,12]:
    cfgs+= [('rot+',s*R),('rot-',-s*R)]
