import numpy as np, torch, model
net = model.load()
w=torch.tensor(np.load('contrast_c0_out_act_k10.npy')); b=-6.6646
torch.manual_seed(3); B=4096
c=torch.rand(B); xi=torch.randn(B,2)
st={'d':torch.zeros(2),'K':11,'lo':0,'thr':0.0,'F':None}
def hk(m,i,o):
    h=i[0]; t=st['t']; k=torch.round((1-t)*20)
    s=h@w+b
    fr=(s>st['thr'])&(k<st['K'])&(k>=st['lo'])
    if st['F'] is not None: st['F'].append(fr.clone())
    return o+fr.float().reshape(-1,1)*st['d']
net.out.register_forward_hook(hk)
orig=net.velocity
def vel(x,t,cc,*a,**kw):
    tt=torch.as_tensor(t,dtype=torch.float32); st['t']=tt.reshape(-1) if tt.dim()>0 else tt
    return orig(x,t,cc,*a,**kw)
net.velocity=vel
def run(d,K=11,thr=0.0,lo=0,rec=False):
    st.update(d=torch.tensor(d,dtype=torch.float32),K=K,thr=thr,lo=lo,F=[] if rec else None)
    with torch.no_grad(): a=np.array(model.decode(net,xi,c))
    return a
a0=run([0,0],rec=True); F=torch.stack(st['F']).numpy().reshape(20,B)
ang=np.degrees(np.arctan2(a0[:,1],a0[:,0])); track=F[:11].any(0)&(ang>80)&(ang<160)
print('track',track.mean())
for thr in [0,2,4,6]:
 for lo,K in [(0,11),(0,8),(4,11)]:
  for mag in [3,6]:
    a=run([0,mag],K,thr,lo); mv=np.linalg.norm(a-a0,axis=1)
    print(thr,lo,K,mag,'track stays',round((mv[track]<0.5).mean(),3),'nontrack moved>0.3',round((mv[~track]>0.3).mean(),4),'>0.15',round((mv[~track]>0.15).mean(),4))
